public void scheduleNightDeployment(ReleasePlan plan) {
    if (!cbsWindowValidator.isAllowed(plan.window())) return;
    deploymentService.deploy(plan);
    notifier.broadcastStatus(plan);
}

public void applySecurityPatch(DependencyUpgrade upgrade) {
    validator.verifyCompatibility(upgrade);
    pipeline.trigger(upgrade.serviceName());
    monitoring.watchPostDeploy(upgrade.serviceName());
}

public SwiftMessage process(SwiftMessage input) {
    validator.validate(input);
    return transformer.applyRules(input);
}
